DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'obra_subpartida_fechas_check') THEN
    ALTER TABLE "public"."obra_subpartida" ADD CONSTRAINT "obra_subpartida_fechas_check" CHECK ("fecha_fin" >= "fecha_inicio") NOT VALID;
  END IF;
  BEGIN
    ALTER TABLE "public"."obra_subpartida" VALIDATE CONSTRAINT "obra_subpartida_fechas_check";
  EXCEPTION WHEN check_violation THEN
    RAISE NOTICE 'La regla % queda sin validar: hay filas antiguas que no la cumplen', 'obra_subpartida_fechas_check';
  END;
END $$

